// HasPlacement applies the HasEdge predicate on the "placement" edge.
func HasPlacement() predicate.BacklinkCheck {
	return predicate.BacklinkCheck(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PlacementTable, PlacementColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPlacementWith applies the HasEdge predicate on the "placement" edge with a given conditions (other predicates).
func HasPlacementWith(preds ...predicate.Placement) predicate.BacklinkCheck {
	return predicate.BacklinkCheck(func(s *sql.Selector) {
		step := newPlacementStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BacklinkCheck) predicate.BacklinkCheck {
	return predicate.BacklinkCheck(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BacklinkCheck) predicate.BacklinkCheck {
	return predicate.BacklinkCheck(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BacklinkCheck) predicate.BacklinkCheck {
	return predicate.BacklinkCheck(sql.NotPredicates(p))
}
